// src/features/product-page/_components/video-showcase.tsx
"use client";
import { useInView } from "framer-motion";
import { useRef } from "react";

export default function VideoShowcase({ videoId }: { videoId: string }) {
  const containerRef = useRef(null);
  const isInView = useInView(containerRef, { amount: 0.6 });

  return (
    <div
      ref={containerRef}
      className="aspect-video rounded-[3rem] overflow-hidden bg-black border border-[var(--border-default)]"
    >
      {isInView && (
        <iframe
          src={`https://www.youtube.com/embed/${videoId}?autoplay=1&mute=1&loop=1&playlist=${videoId}`}
          className="w-full h-full pointer-events-none"
          allow="autoplay"
        />
      )}
    </div>
  );
}
