"use client";

import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Maximize2, X } from "lucide-react";

export default function Gallery({ images }: { images: string[] }) {
  const [selectedImage, setSelectedImage] = useState<string | null>(null);

  return (
    <div className="space-y-4">
      {/* Main Feature Image */}
      <div className="relative aspect-[4/5] rounded-[2.5rem] overflow-hidden bg-[var(--surface-muted)] border border-[var(--border-default)]">
        <img 
          src={images[0]} 
          alt="Product Promo" 
          className="w-full h-full object-cover cursor-zoom-in"
          onClick={() => setSelectedImage(images[0])}
        />
        <div className="absolute top-6 left-6 bg-[var(--brand-primary)] text-[var(--brand-foreground)] px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest">
          Promo
        </div>
      </div>

      {/* Live Images Grid */}
      <div className="grid grid-cols-2 gap-4">
        {images.slice(1).map((img, idx) => (
          <div 
            key={idx} 
            className="group relative aspect-square rounded-[1.5rem] overflow-hidden bg-[var(--surface-muted)] border border-[var(--border-default)] cursor-zoom-in"
            onClick={() => setSelectedImage(img)}
          >
            <div className="absolute inset-0 bg-black/0 group-hover:bg-black/20 transition-all flex items-center justify-center">
              <Maximize2 className="text-white opacity-0 group-hover:opacity-100 transition-opacity" size={20} />
            </div>
            <span className="absolute bottom-3 left-3 bg-white/90 text-black text-[7px] font-black px-1.5 py-0.5 rounded uppercase">Live</span>
            <img src={img} className="w-full h-full object-cover" alt={`Live view ${idx + 1}`} />
          </div>
        ))}
      </div>

      {/* Modern Zoom Modal */}
      <AnimatePresence>
        {selectedImage && (
          <motion.div 
            initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
            className="fixed inset-0 z-[500] bg-black/95 backdrop-blur-xl flex items-center justify-center p-4 md:p-12"
            onClick={() => setSelectedImage(null)}
          >
            <button className="absolute top-10 right-10 text-white hover:rotate-90 transition-transform">
              <X size={32} />
            </button>
            <motion.img 
              initial={{ scale: 0.9, y: 20 }} animate={{ scale: 1, y: 0 }}
              src={selectedImage} 
              className="max-w-full max-h-full object-contain rounded-xl shadow-2xl"
            />
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}